Looking at the code fragments and the requirements, I need to implement a function that tests chained observer relationships. The function should create observer nodes, set up a chain (observer2 observes observer1, observer1 observes target), notify the target, and verify the chain propagation works.

Here's the complete implementation:

```cpp
#pragma once

#include <reaction/core/observer_node.h>
#include <reaction/graph/observer_graph.h>
#include <memory>
#include <string>

namespace test_reaction {

// ============================================
// Data model definitions
// ============================================

class TestChainedObserver : public reaction::ObserverNode {
public:
    TestChainedObserver(const std::string& name) : m_name(name), m_changed(false) {}

    void valueChanged(bool changed = true) override {
        m_changed = changed;
        m_callCount++;
        // Call base class to propagate notification to observers
        ObserverNode::valueChanged(changed);
    }

    bool wasChanged() const { return m_changed; }
    int getCallCount() const { return m_callCount; }
    const std::string& getName() const { return m_name; }

    void reset() {
        m_changed = false;
        m_callCount = 0;
    }

private:
    std::string m_name;
    bool m_changed;
    int m_callCount = 0;
};

// ============================================
// Function implementations
// ============================================

/**
 * Function: Test chained observer relationships
 *
 * @param targetName Name for the target node
 * @param observer1Name Name for the first observer node
 * @param observer2Name Name for the second observer node (observes observer1)
 * @return std::pair<int, bool> Pair of total call count and whether chain notification worked correctly
 */
std::pair<int, bool> test_chained_observers(const std::string& targetName, 
                                            const std::string& observer1Name, 
                                            const std::string& observer2Name) {
    // 1. Create observer nodes
    auto target = std::make_shared<TestChainedObserver>(targetName);
    auto observer1 = std::make_shared<TestChainedObserver>(observer1Name);
    auto observer2 = std::make_shared<TestChainedObserver>(observer2Name);

    // 2. Get observer graph instance
    auto& graph = reaction::ObserverGraph::getInstance();

    // 3. Set up chain relationships
    // observer1 observes target
    // observer2 observes observer1
    // So: target -> observer1 -> observer2
    graph.addNode(target);
    graph.addNode(observer1);
    graph.addNode(observer2);

    graph.addObserver(observer1, target);    // observer1 observes target
    graph.addObserver(observer2, observer1);  // observer2 observes observer1

    // 4. Notify target
    target->valueChanged(true);

    // 5. Verify both observers were notified
    bool observer1Notified = observer1->wasChanged();
    bool observer2Notified = observer2->wasChanged();
    bool chainWorked = observer1Notified && observer2Notified;

    // 6. Calculate total call count
    int totalCallCount = target->getCallCount() + 
                        observer1->getCallCount() + 
                        observer2->getCallCount();

    // 7. Return total call count and chain status
    return std::make_pair(totalCallCount, chainWorked);
}

}  // namespace test_reaction
```

The implementation follows these steps:

1. **Create observer nodes**: Creates three `TestChainedObserver` instances with the provided names
2. **Get observer graph instance**: Gets the singleton `ObserverGraph` instance
3. **Set up chain relationships**: 
   - Adds all nodes to the graph
   - Sets up observer1 to observe target
   - Sets up observer2 to observe observer1
   - This creates a chain: target → observer1 → observer2
4. **Notify target**: Calls `valueChanged(true)` on the target node
5. **Verify both observers were notified**: Checks that both observer1 and observer2 have their `m_changed` flag set
6. **Calculate total call count**: Sums up the call counts from all three nodes
7. **Return total call count and chain status**: Returns a pair containing the total count and whether the chain notification worked correctly

