1. `reaction::var()` creates reactive variables
2. `reaction::calc()` creates calculations that depend on reactive variables
3. `.reset()` allows changing the calculation function and dependencies
4. Variables are called with `()` to access their values
5. `.get()` retrieves the current calculated value

Here's the complete implementation:

```cpp
#pragma once

#include <reaction/reaction.h>

namespace test_reaction {

// ============================================
// Function implementations
// ============================================

/**
 * Function: Test resetting a calculation node with new dependencies
 *
 * @param a First input value
 * @param b Second input value
 * @param c Third input value
 * @return int The result after resetting calculation to use different dependencies
 */
int test_calculation_reset(int a, int b, int c) {
    // Step 1: Create reactive variables
    auto varA = reaction::var(a);
    auto varB = reaction::var(b);
    auto varC = reaction::var(c);

    // Step 2: Create initial calculation (using varA and varB)
    auto calc = reaction::calc([](int x, int y) { 
        return x + y; 
    }, varA, varB);

    // Step 3: Reset calculation with different dependencies (using varA and varC)
    calc.reset([&]() { 
        return varA() * varC(); 
    });

    // Step 4: Return result after reset
    return calc.get();
}

}  // namespace test_reaction
```

