```cpp
#include "test_observer_cache_stats.h"

namespace test_reaction {

void CacheProbeNode::valueChanged(bool changed) {
    // Default implementation - just call base notify
    this->notify(changed);
}

CacheStatsSnapshot test_observer_cache_stats() {
    using namespace reaction;

    // 1. Create CacheProbeNode instances
    auto node1 = std::make_shared<CacheProbeNode>();
    auto node2 = std::make_shared<CacheProbeNode>();
    auto node3 = std::make_shared<CacheProbeNode>();

    // 2. Get observer graph instance
    auto& graph = ObserverGraph::getInstance();

    // 3. Register nodes
    graph.registerNode(node1);
    graph.registerNode(node2);
    graph.registerNode(node3);

    // 4. Set up direct observer relationship
    // node1 observes node2
    graph.addObserver(node2, node1);

    // 5. Set up transitive observer relationship
    // node2 observes node3 (creating chain: node3 -> node2 -> node1)
    graph.addObserver(node3, node2);

    // 6. Create NodeSet to store collected observers
    NodeSet collectedObservers;

    // 7. Populate cache data
    // Query observers to populate the cache
    graph.getObservers(node2, collectedObservers);
    collectedObservers.clear();
    graph.getObservers(node3, collectedObservers);
    collectedObservers.clear();

    // Perform some transitive observer queries to populate cache
    graph.getTransitiveObservers(node3, collectedObservers);
    collectedObservers.clear();
    graph.getTransitiveObservers(node2, collectedObservers);

    // 8. Get cache statistics before cleanup
    auto statsBefore = graph.getCacheStats();

    // 9. Trigger cache cleanup
    graph.triggerCacheCleanup();

    // 10. Get cache statistics after cleanup
    auto statsAfter = graph.getCacheStats();

    // 11. Close all nodes
    graph.closeNode(node1);
    graph.closeNode(node2);
    graph.closeNode(node3);

    // 12. Return cache stats snapshot
    return CacheStatsSnapshot{
        statsBefore.totalEntries,
        statsAfter.totalEntries,
        statsAfter.hitRatio
    };
}

}  // namespace test_reaction
