  EXPECT_TRUE(sequence.strictlyIncreasing);
  EXPECT_LT(sequence.firstValue, sequence.secondValue);
  EXPECT_LT(sequence.secondValue, sequence.thirdValue);
}

}  // namespace test_reaction

