Looking at the test file structure and the `SBOResource` API from the test examples, I need to implement a function that tests SBO (Small Buffer Optimization) storage information.

Based on the test examples in `test/unit/test_sbo.cpp` and the header file, here's the implementation:

```cpp
#pragma once

#include <array>
#include <cstddef>
#include <reaction/memory/sbo_resource.h>

namespace test_reaction {

struct SmallPayload {
    int value;
    bool operator!=(const SmallPayload& other) const = default;
};

struct LargePayload {
    std::array<int, 64> data{};
    bool operator!=(const LargePayload& other) const = default;
};

struct SboStorageStatus {
    bool updateReportedChange;
    bool smallUsingSBO;
    std::size_t smallStackUsage;
    bool largeInitialized;
    bool largeUsingSBO;
};

SboStorageStatus test_sbo_storage_info(int initialSmall,
                                       int updatedSmall,
                                       int largeSeed) {
    using namespace reaction;

    // 1. Create a lambda function to make large payload
    auto makeLargePayload = [](int seed) {
        LargePayload payload;
        for (int i = 0; i < 64; ++i) {
            payload.data[i] = seed + i;
        }
        return payload;
    };

    // 2. Create small SBOResource
    auto smallResource = std::make_shared<SBOResource<SmallPayload>>(SmallPayload{initialSmall});

    // 3. Create large SBOResource
    auto largeResource = std::make_shared<SBOResource<LargePayload>>(makeLargePayload(largeSeed));

    // 4. Update small resource value
    bool updateReportedChange = smallResource->updateValue(SmallPayload{updatedSmall});

    // 5. Get storage information for small resource
    bool smallUsingSBO = smallResource->isUsingSBO();
    std::size_t smallStackUsage = smallResource->getStackUsage();

    // 6. Get storage information for large resource
    bool largeInitialized = largeResource->isInitialized();
    bool largeUsingSBO = largeResource->isUsingSBO();

    // 7. Return SBO storage status
    return SboStorageStatus{
        updateReportedChange,
        smallUsingSBO,
        smallStackUsage,
        largeInitialized,
        largeUsingSBO
    };
}

}  // namespace test_reaction
```

