```cpp
#pragma once

#include <reaction/memory/memory_config.h>
#include <reaction/memory/stack_monitor.h>

namespace test_reaction {

struct StackLimitSnapshot {
    reaction::memory::StackMonitor::UsageStats statsBeforeGuard;
    reaction::memory::StackMonitor::UsageStats statsAfterGuard;
    bool templateAllocationAllowed;
    bool runtimeAllocationAllowed;
    bool guardHeld;
    bool allocationBlockedWhileGuardHeld;
};

StackLimitSnapshot test_stack_monitor_limits() {
    using namespace reaction::memory;

    StackLimitSnapshot snapshot;

    // 1. Enable monitoring
    StackMonitor::setMonitoringEnabled(true);

    // 2. Initialize stack monitor
    StackMonitor::initialize();

    // 3. Get usage statistics before guard
    snapshot.statsBeforeGuard = StackMonitor::getUsageStats();

    // 4. Check if template allocation is allowed
    snapshot.templateAllocationAllowed = StackMonitor::canAllocate<1024>();

    // 5. Check if runtime allocation is allowed
    snapshot.runtimeAllocationAllowed = StackMonitor::canAllocate(1024);

    // 6. Create large StackGuard instance (use a size close to the limit)
    constexpr size_t large_size = SBOConfig::MAX_SBO_STACK_USAGE / 2;
    StackMonitor::StackGuard<large_size> guard;

    // 7. Check if guard succeeded
    snapshot.guardHeld = guard.success();

    // 8. Check if allocation blocked while guard is held
    // Try to allocate more than the remaining limit
    constexpr size_t additional_size = SBOConfig::MAX_SBO_STACK_USAGE;
    snapshot.allocationBlockedWhileGuardHeld = !StackMonitor::canAllocate<additional_size>();

    // 9. Get usage statistics after guard
    snapshot.statsAfterGuard = StackMonitor::getUsageStats();

    // 10. Return stack limit snapshot
    // Guard destructor will run here, releasing the stack usage
    return snapshot;
}

}  // namespace test_reaction
```

